const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',sales:'<path d="M3 3h2l3 12h10l3-9H6"/><circle cx="9" cy="20" r="1"/><circle cx="18" cy="20" r="1"/>',stock:'<path d="m3 7 9-4 9 4v12l-9 3-9-3Z"/><path d="m3 7 9 4 9-4M12 11v11M7 5l10 4"/>',purchase:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',customers:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M17 4a4 4 0 0 1 0 8m2 3a6 6 0 0 1 3 6"/>',expenses:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18M15 14h3"/>',estimator:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8M8 10h1m6 0h1m-8 4h1m6 0h1m-8 4h1m6 0h1"/>',reports:'<path d="M4 3v18h17M8 16v-5m5 5V7m5 9V3"/>',invoice:'<path d="M5 3h14v19l-3-2-4 2-4-2-3 2Z M8 7h8M8 11h8M8 15h4"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="m12 2 2 3 4 1 1 4 3 2-3 2-1 4-4 1-2 3-2-3-4-1-1-4-3-2 3-2 1-4 4-1Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',profit:'<path d="m3 17 6-6 4 3 8-10M15 4h6v6"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.home}</svg>`;
let lang='bn',page='home',cart=[],mode='sales',filter='',search='',pending=null;
const t=(bn,en)=>lang==='bn'?bn:en;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>new Intl.NumberFormat(lang==='bn'?'bn-BD':'en-BD',{maximumFractionDigits:2}).format(n);
const money=n=>'৳'+num(n);const round=n=>Math.round((n+Number.EPSILON)*100)/100;
function seedBase(){return {products:[{id:1,bn:'মিনিকেট চাল',en:'Miniket rice',unit:'kg',stock:80,min:20,buy:60,price:70,emoji:'🌾',cat:'Grains'},{id:2,bn:'মসুর ডাল',en:'Red lentils',unit:'kg',stock:12,min:20,buy:100,price:125,emoji:'🫘',cat:'Grains'},{id:3,bn:'সয়াবিন তেল',en:'Soybean oil',unit:'L',stock:38,min:15,buy:150,price:175,emoji:'🫙',cat:'Essentials'},{id:4,bn:'চিনি',en:'Sugar',unit:'kg',stock:8,min:15,buy:110,price:130,emoji:'🍚',cat:'Essentials'},{id:5,bn:'আটা',en:'Whole wheat flour',unit:'kg',stock:45,min:15,buy:45,price:55,emoji:'🌾',cat:'Grains'},{id:6,bn:'লবণ',en:'Salt',unit:'kg',stock:25,min:10,buy:30,price:40,emoji:'🧂',cat:'Essentials'}],customers:[{id:1,bn:'রহিম স্টোর',en:'Rahim Store',phone:'01712-345678',due:2400},{id:2,bn:'সালমা বেগম',en:'Salma Begum',phone:'01812-456789',due:1250},{id:3,bn:'করিম ট্রেডার্স',en:'Karim Traders',phone:'01912-567890',due:4600}],sales:[{id:1003,customer:2,total:875,paid:875,cost:750,items:[{name:'Soybean oil',bn:'সয়াবিন তেল',qty:5,unit:'L',price:175}],time:'12:45'},{id:1002,customer:0,total:550,paid:550,cost:450,items:[{name:'Whole wheat flour',bn:'আটা',qty:10,unit:'kg',price:55}],time:'11:20'},{id:1001,customer:1,total:1400,paid:1000,cost:1200,items:[{name:'Miniket rice',bn:'মিনিকেট চাল',qty:20,unit:'kg',price:70}],time:'10:10'}],expenses:[{name:'পরিবহন / Transport',amount:150,date:businessDate()}],purchases:[],receipts:[]}}
function seed(){return upgradeData(seedBase(),true)}
let db;try{db=JSON.parse(localStorage.getItem('hisab-demo-v1'))||seed();if(!Array.isArray(db.products))db=seed()}catch{db=seed()}
function save(){try{localStorage.setItem('hisab-demo-v1',JSON.stringify(db))}catch{toast(t('এই সেশনে সংরক্ষিত; ব্রাউজার স্টোরেজ নেই','Saved for this session; browser storage unavailable'))}}
const name=p=>esc(lang==='bn'?p.bn:p.en);const totalSales=()=>db.sales.reduce((s,x)=>s+x.total,0);const expenseTotal=()=>db.expenses.reduce((s,x)=>s+x.amount,0);const profit=()=>round(db.sales.reduce((s,x)=>s+x.total-x.cost,0)-expenseTotal());const dues=()=>db.customers.reduce((s,x)=>s+x.due,0);const low=()=>db.products.filter(x=>x.stock<=x.min);
const todaySalesRecords=()=>db.sales.filter(s=>s.date===businessDate());
const todaySalesTotal=()=>round(todaySalesRecords().reduce((sum,s)=>sum+(Number(s.total)||0),0));
const todayExpenseRecords=()=>db.expenses.filter(e=>e.date===businessDate());
const todayExpenseTotal=()=>round(todayExpenseRecords().reduce((sum,e)=>sum+(Number(e.amount)||0),0));
const todayProfit=()=>round(todaySalesRecords().reduce((sum,s)=>sum+(Number(s.total)||0)-(Number(s.cost)||0),0)-todayExpenseTotal());
function lastSevenDaysSales(){const today=businessDate(),anchor=new Date(today+'T12:00:00Z');return Array.from({length:7},(_,index)=>{const date=new Date(anchor);date.setUTCDate(date.getUTCDate()-(6-index));const key=date.toISOString().slice(0,10);return {date:key,total:round(db.sales.filter(s=>s.date===key).reduce((sum,s)=>sum+(Number(s.total)||0),0)),label:key===today?t('আজ','Today'):date.toLocaleDateString(lang==='bn'?'bn-BD':'en-GB',{weekday:'short',timeZone:'Asia/Dhaka'})}})}
function hasUndatedDashboardRecords(){return db.sales.some(s=>!validDate(s.date))||db.expenses.some(e=>!validDate(e.date))}
const pages={home:['হোম','Overview'],shops:['দোকানদারের তালিকা','Shops'],sales:['বিক্রি','Sales'],purchase:['কেনাকাটা','Purchases'],stock:['পণ্য ও স্টক','Products & stock'],customers:['ক্রেতার বাকি','Customers & dues'],expenses:['খরচ','Expenses'],estimator:['লাভের হিসাব','Estimator'],reports:['রিপোর্ট','Reports'],invoice:['ইনভয়েস','Invoices'],settings:['সেটিংস','Settings']};
function label(k){return t(...pages[k])}function navigate(k){page=k;search='';filter='';if(k==='purchase'||k==='sales'){if(mode!==k)cart=[];mode=k}render();window.scrollTo(0,0)}
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3200)}
function btn(text,action,primary=false,ic='plus'){return `<button class="btn ${primary?'primary':''}" ${action}>${icon(ic)}${text}</button>`}
function render(){document.documentElement.lang=lang;document.querySelector('#app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="logo">হ</span><div><strong>হিসাব</strong><small>YOUR BUSINESS, SIMPLIFIED</small></div></div><div class="shop"><b>${t('রহিম জেনারেল স্টোর','Rahim General Store')}</b><small>${t('মিরপুর, ঢাকা · নমুনা দোকান','Mirpur, Dhaka · Sample shop')}</small></div><div class="navlabel">${t('আমার ব্যবসা','WORKSPACE')}</div><nav class="nav">${Object.keys(pages).map(k=>`<button class="${page===k?'active':''}" onclick="navigate('${k}')">${icon(k)}${label(k)}${k==='stock'?`<span class="badge">${num(low().length)}</span>`:''}</button>`).join('')}</nav><footer><span class="avatar">র</span><div><b>${t('রহিম উদ্দিন','Rahim Uddin')}</b><small>${t('মালিক · ডেমো প্রোফাইল','Owner · Demo profile')}</small></div></footer></aside><div class="workspace"><header class="topbar"><span class="crumb">${t('আমার ব্যবসা','My business')} <span style="padding:0 12px;color:#b5beb8">/</span> <b>${label(page)}</b></span><div class="mobilebrand"><span class="logo">হ</span> হিসাব</div><div class="topactions"><span class="demo">${t('ডেমো · নমুনা তথ্য','DEMO · SAMPLE DATA')}</span><button class="lang" onclick="lang=lang==='bn'?'en':'bn';render()">${lang==='bn'?'English':'বাংলা'}</button><span class="avatar">র</span></div></header><main class="main">${content()}<div class="footnote"><span>${t('শুধু ফ্রন্টএন্ড ডেমো · এই ব্রাউজারে নমুনা তথ্য সংরক্ষিত','Frontend demo only · Sample changes stay in this browser')}</span><button class="link" onclick="resetDemo()">${t('ডেমো রিসেট','Reset demo')}</button></div></main></div><nav class="bottomnav">${['home','sales','stock','estimator','more'].map(k=>`<button class="${page===k?'active':''}" onclick="${k==='more'?'more()':`navigate('${k}')`}">${icon(k)}${k==='more'?t('আরও','More'):label(k)}</button>`).join('')}</nav>`}
function head(title,sub,action=''){return `<div class="pagehead"><div><div class="eyebrow">${t('আপনার প্রতিদিনের ব্যবসার সঙ্গী','YOUR EVERYDAY BUSINESS COMPANION')}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function metric(title,value,sub,ic){return `<div class="metric"><div class="metric-top">${title}<span>${icon(ic)}</span></div><strong>${value}</strong><small>${sub}</small></div>`}
function content(){if(page==='home')return home();if(page==='shops')return shops();if(page==='sales'||page==='purchase')return pos();if(page==='stock')return stock();if(page==='customers')return customers();if(page==='expenses')return expenses();if(page==='estimator')return estimator();if(page==='invoice')return invoices();if(page==='reports')return reports();return settings()}
function home(){const currentSales=todaySalesRecords(),week=lastSevenDaysSales(),weekTotal=round(week.reduce((sum,day)=>sum+day.total,0)),maxDay=Math.max(0,...week.map(day=>day.total));const bars=week.map(day=>{const h=day.total>0?Math.max(4,day.total/(maxDay||1)*150):0;const label=`${day.label}: ${money(day.total)}`;return `<div class="barcol" title="${esc(label)}" aria-label="${esc(label)}"><div class="bar" style="height:${h}px;${h===0?'min-height:0;':''}"></div><small>${esc(day.label)}</small></div>`}).join('');return head(t('আসসালামু আলাইকুম, রহিম!','A good day for business, Rahim.'),t('চলুন, আজকের ব্যবসার হিসাব দেখে নিই।','Here’s how your shop is doing today.'),`<span class="btn date">${new Date().toLocaleDateString(lang==='bn'?'bn-BD':'en-GB',{day:'numeric',month:'long',year:'numeric'})}</span>`)+`<section class="welcome"><div><h2>${t('ছোট দোকান। বড় স্বপ্ন।','Small shop. Big ambitions.')}</h2><p>${t('বিক্রি থেকে বাকি — সব হিসাব এক জায়গায়।','From the first sale to the last taka. Everything in one place.')}</p></div><div class="row">${btn(t('বিক্রি করুন','New sale'),`onclick="navigate('sales')"`,false,'plus')}${btn(t('পণ্য কিনুন','Buy stock'),`onclick="navigate('purchase')"`,false,'purchase')}</div></section><section class="metrics">${metric(t('আজকের বিক্রি','Today’s sales'),money(todaySalesTotal()),t(`${num(currentSales.length)}টি সম্পন্ন বিক্রি`,`${currentSales.length} completed sales today`),'sales')}${metric(t('আজকের লাভ','Today’s profit'),money(todayProfit()),t('আজকের বিক্রি থেকে পণ্যের খরচ ও নথিভুক্ত খরচ বাদে','Today’s sales less product costs and recorded expenses'),'profit')}${metric(t('ক্রেতার কাছে পাওনা','Customer dues'),money(dues()),t('আগের বাকি সহ বর্তমান পাওনা','Current balance, including opening dues'),'customers')}${metric(t('আজকের খরচ','Today’s expenses'),money(todayExpenseTotal()),t('আজকের তারিখসহ সংরক্ষিত খরচ','Expenses recorded with today’s date'),'expenses')}</section><div class="grid"><section class="panel"><div class="panelhead"><div><h2>${t('বিক্রির চিত্র','Sales at a glance')}</h2><p>${t('গত ৭ দিনের রেকর্ডকৃত বিক্রি','Recorded sales over the last 7 days')}</p></div><span class="tag">${t('গত ৭ দিন','Last 7 days')}</span></div><div class="charttotal">${money(weekTotal)}<small>${t('৭ দিনের মোট বিক্রি','sales over 7 days')}</small></div><div class="chart" role="img" aria-label="${t('গত সাত দিনের প্রতিদিনের বিক্রির গ্রাফ','Daily sales chart for the last seven days')}">${bars}</div></section><section class="panel"><div class="panelhead"><div><h2>${t('স্টক একটু দেখে নিন','A little stock check')}</h2><p>${t('এই পণ্যগুলো শীঘ্রই কিনতে হবে','These items may need a refill soon')}</p></div><span class="tag amber">${num(low().length)}</span></div>${low().map(p=>`<div class="stockrow"><div class="producticon">${p.emoji}</div><div class="detail"><b>${name(p)}</b><small>${t('সর্বনিম্ন','Minimum')} ${num(p.min)} ${p.unit}</small></div><span class="tag amber">${num(p.stock)} ${p.unit}</span></div>`).join('')||`<p>${t('সব পণ্যের পর্যাপ্ত স্টক আছে','All products are well stocked')}</p>`}<button class="link" style="margin-top:18px" onclick="navigate('stock')">${t('সব স্টক দেখুন →','View all stock →')}</button></section></div>${hasUndatedDashboardRecords()?`<p class="statebanner" role="note">${t('কিছু পুরোনো বিক্রি বা খরচের তারিখ সংরক্ষিত নেই। সেগুলো আজকের অঙ্ক ও গত ৭ দিনের গ্রাফে ধরা হয়নি; পুরোনো রেকর্ড মুছে ফেলা হয়নি।','Some older sales or expenses have no saved date. They are excluded from today’s figures and the 7-day chart; the original records are kept.')}</p>`:''}`}
function party(id){return id?name(db.customers.find(c=>c.id===id)||{bn:'ক্রেতা',en:'Customer'}):t('নগদ ক্রেতা','Walk-in customer')}
function salesTable(list){return `<div class="tablewrap"><table><thead><tr><th>${t('ইনভয়েস','Invoice')}</th><th>${t('ক্রেতা','Customer')}</th><th>${t('পরিমাণ','Amount')}</th><th>${t('অবস্থা','Status')}</th><th>${t('বিস্তারিত','Details')}</th></tr></thead><tbody>${list.map(s=>`<tr><td><b>#INV-${s.id}</b><small>${s.time}</small></td><td>${party(s.customer)}</td><td><b>${money(s.total)}</b></td><td><span class="tag ${s.paid<s.total?'amber':''}">${s.paid<s.total?t('আংশিক পরিশোধ','Part paid'):t('পরিশোধিত','Paid')}</span></td><td><button class="link" onclick="invoice(${s.id})">${t('দেখুন ↗','View ↗')}</button></td></tr>`).join('')}</tbody></table></div>`}
function pos(){const purchase=page==='purchase';const categories=[...new Set(db.products.map(p=>p.cat).filter(Boolean))];return head(purchase?t('পণ্য কিনুন','Buy stock'):t('নতুন বিক্রি','Make a sale'),t('পণ্য বাছুন, পরিমাণ দিন, তারপর যাচাই করুন।','Choose products, set quantities, then review.'))+`<div class="pos"><section><div class="toolbar"><input aria-label="${t('পণ্য খুঁজুন','Search products')}" placeholder="${t('পণ্যের নাম লিখুন…','Search your products…')}" oninput="search=this.value;renderProducts()"><select style="max-width:160px" aria-label="Category" onchange="filter=this.value;renderProducts()"><option value="">${t('সব পণ্য','All products')}</option>${categories.map(cat=>`<option value="${esc(cat)}">${cat==='Grains'?t('শস্য','Grains'):cat==='Essentials'?t('নিত্যপণ্য','Essentials'):esc(cat)}</option>`).join('')}</select>${purchase?btn(t('নতুন পণ্য যোগ করুন','Add product'),'onclick=\"addProduct()\"',true,'plus'):''}</div><div class="productgrid" id="productlist">${productCards()}</div></section><section class="panel"><div class="panelhead"><h2>${purchase?t('ক্রয়ের তালিকা','Purchase basket'):t('বিক্রির তালিকা','Sale basket')}</h2><button class="link" onclick="cart=[];render()">${t('খালি করুন','Clear')}</button></div><div id="cart">${cartView()}</div></section></div>`}
function productCards(){return db.products.filter(p=>(p.bn+' '+p.en).toLowerCase().includes(search.toLowerCase())&&(!filter||p.cat===filter)).map(p=>`<div class="producttile"><button class="productcard" onclick="addCart(${p.id})" ${mode==='sales'&&p.stock<=0?'disabled':''}><div class="producticon">${p.emoji}</div><b>${name(p)}</b><strong>${money(mode==='purchase'?p.buy:p.price)} <small>/ ${p.unit}</small></strong><small>${t('স্টক','In stock')}: ${num(p.stock)} ${p.unit}</small></button>${mode==='purchase'?`<button class="productdelete" type="button" title="${t('পণ্য মুছুন','Delete product')}" aria-label="${t('পণ্য মুছুন','Delete product')} ${name(p)}" onclick="deleteProduct(${p.id})">🗑</button>`:''}</div>`).join('')||`<div class="empty">${t('পণ্য পাওয়া যায়নি','No matching products')}</div>`}
function renderProducts(){document.querySelector('#productlist').innerHTML=productCards()}
function addCart(id){const p=db.products.find(x=>x.id===id),c=cart.find(x=>x.id===id);if(mode==='sales'&&(c?.qty||0)+1>p.stock)return toast(t('পর্যাপ্ত স্টক নেই','Not enough stock'));if(c)c.qty++;else cart.push({id,qty:1});document.querySelector('#cart').innerHTML=cartView()}
function cartTotal(){return round(cart.reduce((s,c)=>{let p=db.products.find(x=>x.id===c.id);return s+c.qty*(mode==='purchase'?p.buy:p.price)},0))}
function changeQty(id,q){const p=db.products.find(x=>x.id===id);q=Number(q);if(!Number.isFinite(q)||q<0)return;if(mode==='sales'&&q>p.stock){toast(t('পর্যাপ্ত স্টক নেই','Not enough stock'));q=p.stock}if(q===0)cart=cart.filter(c=>c.id!==id);else cart.find(c=>c.id===id).qty=round(q);document.querySelector('#cart').innerHTML=cartView()}
function cartView(){if(!cart.length)return `<div class="empty">${icon('sales')}<p>${t('পণ্য যোগ করে শুরু করুন','Add a product to get started')}</p></div>`;return cart.map(c=>{let p=db.products.find(x=>x.id===c.id);return `<div class="cartrow"><div class="row between"><b>${name(p)}</b><b>${money(c.qty*(mode==='purchase'?p.buy:p.price))}</b></div><div class="row between" style="margin-top:10px"><small class="muted">${money(mode==='purchase'?p.buy:p.price)} / ${p.unit}</small><div class="quantity"><button aria-label="Reduce quantity" onclick="changeQty(${c.id},${c.qty-1})">−</button><input aria-label="Quantity" type="number" min="0" step="0.01" value="${c.qty}" onchange="changeQty(${c.id},this.value)"><button aria-label="Increase quantity" onclick="changeQty(${c.id},${c.qty+1})">+</button></div></div></div>`}).join('')+`<div class="summary"><div class="row between total"><span>${t('মোট','Total')}</span><span>${money(cartTotal())}</span></div><div class="field"><label>${mode==='purchase'?t('সরবরাহকারী','Supplier'):t('ক্রেতা','Customer')}</label>${mode==='purchase'?`<select id="customer"><option value="">${t('দোকান বাছুন','Choose a shop')}</option>${db.customers.filter(c=>!c.archivedAt).map(c=>`<option value="${c.id}">${name(c)} · ${esc(c.code)}</option>`).join('')}</select>`:`<select id="customer"><option value="0">${t('নগদ ক্রেতা','Walk-in customer')}</option>${db.customers.filter(c=>!c.archivedAt).map(c=>`<option value="${c.id}">${name(c)} · ${esc(c.code||'')}</option>`).join('')}</select>`}</div><div class="field"><label>${t('পরিশোধিত টাকা','Amount paid')}</label><input id="paid" type="number" min="0" step="0.01" value="${cartTotal()}" oninput="updateDue()"></div><div class="field"><label>${t('পেমেন্ট মাধ্যম','Payment method')}</label><select id="method"><option>Cash</option><option>bKash</option><option>Nagad</option><option>Bank</option></select></div><div class="row between"><span>${t('বাকি','Due')}</span><b id="due">${money(0)}</b></div><p id="cartError" class="error" role="alert"></p><button class="btn primary full" onclick="review()">${t('যাচাই করুন','Review transaction')}${icon('arrow')}</button></div>`}
function updateDue(){document.querySelector('#due').textContent=money(Math.max(0,cartTotal()-Number(document.querySelector('#paid').value)))}
function review(){let total=cartTotal(),paid=Number(document.querySelector('#paid').value),customer=document.querySelector('#customer').value;let error='';if(!Number.isFinite(paid)||paid<0||paid>total)error=t('০ থেকে মোট টাকার মধ্যে পরিশোধ লিখুন','Enter a paid amount between zero and the total');if(mode==='sales'&&paid<total&&customer==='0')error=t('বাকি বিক্রির জন্য একজন ক্রেতা বাছুন','Choose a customer for a credit sale');if(mode==='purchase'&&!customer.trim())error=t('সরবরাহকারীর নাম লিখুন','Enter a supplier name');if(customer!=='0'&&!db.customers.some(c=>c.id===Number(customer)&&!c.archivedAt))error=t('তালিকা থেকে সক্রিয় দোকান বাছুন','Choose an active shop from the list');if(error){document.querySelector('#cartError').textContent=error;return}pending={mode,total,paid:round(paid),customer:Number(customer),date:businessDate(),method:document.querySelector('#method').value,items:cart.map(x=>({...x}))};show(`<h2>${t('সব ঠিক আছে?','Everything look right?')}</h2><div class="notice">${t('শুধু ডেমোর নমুনা তথ্য বদলাবে।','Only the sample data in this demo will change.')}</div><div class="receipt">${cart.map(c=>`<div class="row between"><span>${name(db.products.find(p=>p.id===c.id))}</span><b>${num(c.qty)}</b></div>`).join('')}<div class="row between"><b>${t('মোট','Total')}</b><b>${money(total)}</b></div><div class="row between"><span>${t('পরিশোধিত','Paid')}</span><span>${money(paid)}</span></div><div class="row between"><span>${t('বাকি','Due')}</span><b>${money(total-paid)}</b></div></div><button class="btn primary full" onclick="confirmTransaction(this)">${icon('check')}${t('নিশ্চিত করুন','Confirm transaction')}</button>`)}
function confirmTransaction(button){if(!pending)return;button.disabled=true;const x=pending;pending=null;let items=[],cost=0;for(const c of x.items){let p=db.products.find(p=>p.id===c.id);if(x.mode==='sales'&&p.stock<c.qty){closeDialog();return toast(t('স্টক বদলেছে, আবার যাচাই করুন','Stock changed. Review again.'))}}for(const c of x.items){let p=db.products.find(p=>p.id===c.id);p.stock=round(p.stock+(x.mode==='sales'?-c.qty:c.qty));cost+=c.qty*p.buy;items.push({name:p.en,bn:p.bn,qty:c.qty,unit:p.unit,price:x.mode==='sales'?p.price:p.buy})}if(x.mode==='sales'){const id=Math.max(1000,...db.sales.map(s=>s.id))+1;db.sales.unshift({id,date:x.date,customer:x.customer,shopSnapshot:shopSnapshot(x.customer),total:x.total,paid:x.paid,cost:round(cost),items,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),method:x.method});if(x.customer)db.customers.find(c=>c.id===x.customer).due=round(db.customers.find(c=>c.id===x.customer).due+x.total-x.paid);save();cart=[];render();invoice(id)}else{db.purchases.unshift({...x,shopId:x.customer,shopSnapshot:shopSnapshot(x.customer),lineItems:items,id:Date.now()});save();cart=[];closeDialog();navigate('stock');toast(t('ক্রয় সংরক্ষিত, স্টক বেড়েছে','Purchase saved. Stock updated.'))}}
function stock(){return head(t('পণ্য ও স্টক','Products & stock'),t('কী আছে, কত আছে — এক নজরে।','What’s on your shelves, at a glance.'),btn(t('পণ্য যোগ করুন','Add product'),`onclick="addProduct()"`,true))+`<section class="metrics">${metric(t('মোট পণ্য','Products'),num(db.products.length),t('সক্রিয় পণ্য','Active products'),'stock')}${metric(t('স্টকের মূল্য','Stock value'),money(db.products.reduce((s,p)=>s+p.stock*p.buy,0)),t('নমুনা ক্রয়মূল্য অনুযায়ী','At sample purchase costs'),'reports')}${metric(t('কম স্টক','Low stock'),num(low().length),t('কেনার সময় হয়েছে','Ready for a refill'),'purchase')}${metric(t('ক্রয়ের বাকি','Supplier dues'),money(db.purchases.reduce((s,p)=>s+p.total-p.paid,0)),t('এই ডেমোতে নতুন ক্রয়','New demo purchases'),'customers')}</section><section class="panel"><div class="toolbar"><input placeholder="${t('পণ্য খুঁজুন…','Search products…')}" aria-label="Search stock" oninput="stockFilter(this.value)"></div><div class="tablewrap"><table><thead><tr><th>${t('পণ্য','Product')}</th><th>${t('বিক্রয়মূল্য','Selling price')}</th><th>${t('স্টক','Stock')}</th><th>${t('অবস্থা','Status')}</th><th></th></tr></thead><tbody id="stockrows">${stockRows('')}</tbody></table></div></section>`}
function stockRows(q){return db.products.filter(p=>(p.en+p.bn).toLowerCase().includes(q.toLowerCase())).map(p=>`<tr><td><div class="row"><span class="producticon">${p.emoji}</span><div><b>${name(p)}</b><small>SKU-${String(p.id).padStart(3,'0')} · ${p.unit}</small></div></div></td><td>${money(p.price)}</td><td><b>${num(p.stock)} ${p.unit}</b></td><td><span class="tag ${p.stock<=p.min?'amber':''}">${p.stock<=p.min?t('কম স্টক','Low stock'):t('পর্যাপ্ত','In stock')}</span></td><td><button class="link" onclick="navigate('purchase');addCart(${p.id})">${t('কিনুন +','Restock +')}</button> <button class="link product-remove-link" aria-label="${t('পণ্য মুছুন','Delete product')} ${name(p)}" onclick="deleteProduct(${p.id})">🗑 ${t('মুছুন','Delete')}</button></td></tr>`).join('')}
function stockFilter(q){document.querySelector('#stockrows').innerHTML=stockRows(q)}
function show(html){const d=document.querySelector('#dialog');d.innerHTML=`<button class="close no-print" aria-label="Close" onclick="closeDialog()">×</button>${html}`;if(!d.open)d.showModal()}
function closeDialog(){document.querySelector('#dialog').close();pending=null}
function addProduct(){show(`<h2>${t('নতুন পণ্য','Add a product')}</h2><form onsubmit="createProduct(event)"><div class="field"><label>${t('বাংলা নাম','Bangla name')}</label><input name="bn" required maxlength="70"></div><div class="field"><label>English name</label><input name="en" required maxlength="70"></div><div class="formgrid">${[['buy',t('ক্রয়মূল্য','Buying price')],['price',t('বিক্রয়মূল্য','Selling price')],['stock',t('শুরুর স্টক','Opening stock')],['min',t('সর্বনিম্ন স্টক','Minimum stock')]].map(([n,l])=>`<div class="field"><label>${l}</label><input name="${n}" type="number" min="0" max="1000000" step="0.01" value="0" required></div>`).join('')}</div><div class="field"><label>${t('একক','Unit')}</label><select name="unit"><option value="kg">kg</option><option value="L">L</option><option value="piece">${t('পিস','piece')}</option></select></div><div class="field"><label>${t('পণ্যের ক্যাটাগরি','Product category')}</label><select name="cat"><option value="Grains">${t('শস্য','Grains')}</option><option value="Essentials">${t('নিত্যপণ্য','Essentials')}</option></select></div><div class="row wrap"><button type="button" class="btn" onclick="closeDialog()">${t('বাতিল করুন','Cancel')}</button><button class="btn primary" type="submit">${t('পণ্য সংরক্ষণ','Save product')}</button></div></form>`) }
function createProduct(e){e.preventDefault();const f=new FormData(e.target),bn=String(f.get('bn')||'').trim(),en=String(f.get('en')||'').trim(),buy=Number(f.get('buy')),price=Number(f.get('price')),stock=Number(f.get('stock')),min=Number(f.get('min'));if(!bn||!en||![buy,price,stock,min].every(v=>Number.isFinite(v)&&v>=0)||buy>1000000||price>1000000||stock>1000000||min>1000000){toast(t('পণ্যের তথ্য সঠিকভাবে দিন','Please enter valid product details'));return}const nextId=Math.max(0,...db.products.map(p=>Number(p.id)||0))+1;db.products.push({id:nextId,bn,en,buy,price,stock,min,unit:String(f.get('unit')||'kg'),cat:String(f.get('cat')||'Essentials'),emoji:'📦'});save();closeDialog();render();toast(t('পণ্য যোগ হয়েছে','Product added'))}
function customers(){return head(t('ক্রেতা ও বাকি','Customers & dues'),t('সম্পর্ক ভালো থাকুক, হিসাব পরিষ্কার থাকুক।','Good relationships start with clear accounts.'))+`<div class="notice">${t('বর্তমান পাওনা','Current customer dues')}: <b>${money(dues())}</b> · ${t('আগের বাকি এবং নতুন বিক্রি অন্তর্ভুক্ত','Includes opening balances and new sales')}</div><section class="panel">${db.customers.map(c=>`<div class="stockrow"><span class="avatar">${name(c).slice(0,1)}</span><div class="detail"><b>${name(c)}</b><small>${c.phone}</small></div><b>${money(c.due)}</b><button class="btn small" onclick="collect(${c.id})" ${c.due<=0?'disabled':''}>${t('টাকা নিন','Collect')}</button></div>`).join('')}</section>`}
function collect(id){const c=db.customers.find(c=>c.id===id);show(`<h2>${t('বাকি টাকা নিন','Collect a payment')}</h2><p>${name(c)} · ${t('বাকি','Due')}: <b>${money(c.due)}</b></p><form onsubmit="receive(event,${id})"><div class="field"><label>${t('কত টাকা পেয়েছেন?','Amount received')}</label><input name="amount" type="number" min="0.01" max="${c.due}" step="0.01" required value="${c.due}"></div><div class="notice">${t('এটি নতুন বিক্রি নয়। শুধু পাওনা কমবে।','This reduces the outstanding balance. It is not a new sale.')}</div><button class="btn primary full">${t('পেমেন্ট সংরক্ষণ','Save payment')}</button></form>`)}
function receive(e,id){e.preventDefault();const a=round(+new FormData(e.target).get('amount')),c=db.customers.find(c=>c.id===id);if(!(a>0&&a<=c.due))return;c.due=round(c.due-a);let remaining=a;for(const s of [...db.sales].reverse().filter(s=>s.customer===id)){const n=Math.min(s.total-s.paid,remaining);s.paid=round(s.paid+n);remaining=round(remaining-n);if(!remaining)break}db.receipts.push({id:Date.now(),date:businessDate(),customer:id,shopSnapshot:shopSnapshot(id),amount:a});save();closeDialog();render();toast(t('পেমেন্ট সংরক্ষিত','Payment recorded'))}
function deleteProduct(id){const p=db.products.find(x=>x.id===id);if(!p)return;show(`<h2>${t('পণ্য মুছে ফেলবেন?','Delete this product?')}</h2><p>${t('আপনি কি','Are you sure you want to delete')} <b>${name(p)}</b> ${t('পণ্যটি সক্রিয় পণ্যের তালিকা থেকে মুছে ফেলতে চান?','from the active product list?')}</p><p class="notice">${t('পুরোনো বিক্রি, কেনাকাটা ও ইনভয়েসের সংরক্ষিত বিবরণ অক্ষত থাকবে। এই পণ্যটি বর্তমান কার্টে থাকলে কার্ট থেকেও সরানো হবে।','Past sales, purchases and invoice item details will be kept. This item will also be removed from the current cart.')}</p><div class="row wrap"><button class="btn" type="button" onclick="closeDialog()">${t('বাতিল করুন','Cancel')}</button><button class="btn danger" type="button" onclick="confirmDeleteProduct(${p.id})">${t('মুছে ফেলুন','Delete product')}</button></div>`)}
function confirmDeleteProduct(id){const product=db.products.find(p=>p.id===id);if(!product)return;for(const sale of db.sales){if(!Array.isArray(sale.items))continue;sale.items=sale.items.map(item=>{if(item.name||item.bn)return item;const source=db.products.find(p=>p.id===Number(item.id??item.productId));return source?{...item,name:source.en,bn:source.bn,unit:item.unit||source.unit,price:Number.isFinite(Number(item.price))?Number(item.price):source.price}:item})}for(const purchase of db.purchases){const raw=Array.isArray(purchase.items)?purchase.items:[],saved=Array.isArray(purchase.lineItems)?purchase.lineItems:[];if(!saved.length&&raw.length)purchase.lineItems=raw.map(item=>{if(item.name||item.bn)return {...item};const source=db.products.find(p=>p.id===Number(item.id??item.productId));return source?{name:source.en,bn:source.bn,qty:item.qty,unit:item.unit||source.unit,price:Number.isFinite(Number(item.price))?Number(item.price):source.buy}:item})}db.products=db.products.filter(p=>p.id!==id);cart=cart.filter(item=>item.id!==id);save();closeDialog();render();toast(t('পণ্যটি তালিকা থেকে মুছে ফেলা হয়েছে','Product removed from the active list'))}
function expenses(){return head(t('দৈনন্দিন খরচ','Everyday expenses'),t('ছোট খরচও হিসাবে থাকুক।','Keep the little costs in the picture.'),btn(t('খরচ যোগ করুন','Add expense'),'onclick=\"expenseForm()\"',true))+`<div class="metrics">${metric(t('মোট খরচ','Total expenses'),money(expenseTotal()),t('আজকের নমুনা তথ্য','Today’s sample records'),'expenses')}</div><section class="panel">${db.expenses.map(e=>`<div class="stockrow"><span class="producticon">${icon('expenses')}</span><div class="detail"><b>${esc(e.name)}${e.description?` — ${esc(e.description)}`:''}</b><small>${t('আজ · নগদ','Today · Cash')}</small></div><b>${money(e.amount)}</b></div>`).join('')}</section>`}
function expenseForm(){show(`<h2>${t('খরচ যোগ করুন','Add an expense')}</h2><form onsubmit="saveExpense(event)"><div class="field"><label>${t('খরচের ধরন','Category')}</label><select name="name" id="expenseCategory" onchange="toggleOtherExpense()">${['পরিবহন / Transport','দোকান ভাড়া / Rent','বিদ্যুৎ / Electricity','বেতন / Salary','অন্যান্য / Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field" id="otherExpenseField" style="display:none"><label>${t('খরচের বিবরণ','Expense description')}</label><input type="text" name="description" id="expenseDescription" maxlength="160" placeholder="${t('কীসের খরচ হয়েছে লিখুন','Describe this expense')}"></div><div class="field"><label>${t('টাকা','Amount')}</label><input type="number" name="amount" min="0.01" max="10000000" step="0.01" required></div><button class="btn primary full">${t('সংরক্ষণ করুন','Save expense')}</button></form>`);toggleOtherExpense()}
function toggleOtherExpense(){const category=document.querySelector('#expenseCategory'),field=document.querySelector('#otherExpenseField'),description=document.querySelector('#expenseDescription');if(!category||!field||!description)return;const isOther=category.value==='অন্যান্য / Other';field.style.display=isOther?'block':'none';description.required=isOther;if(!isOther)description.value=''}
function saveExpense(e){e.preventDefault();const f=new FormData(e.target),category=String(f.get('name')||''),description=String(f.get('description')||'').trim(),isOther=category==='অন্যান্য / Other';if(isOther&&!description){toast(t('অন্যান্য খরচের বিবরণ লিখুন','Please describe the other expense'));document.querySelector('#expenseDescription')?.focus();return}db.expenses.unshift({name:category,category,description:isOther?description:'',amount:round(+f.get('amount')),date:businessDate()});save();closeDialog();render();toast(t('খরচ সংরক্ষিত','Expense saved'))}
function estimator(){return head(t('কেনার আগে, লাভের হিসাব','Plan before you purchase'),t('দাম বদলে দেখুন। ব্যবসার সিদ্ধান্ত নিন বুঝে।','Try different numbers. Make your next move with confidence.'))+`<div class="notice">${t('এটি শুধু সম্ভাব্য হিসাব। আপনার আসল স্টক বা টাকায় কোনো পরিবর্তন হবে না।','A what-if calculator only. Your stock, sales and balances will not change.')}</div><div class="estimate"><section class="panel"><div class="panelhead"><h2>${t('আপনার পরিকল্পনা','Your purchase plan')}</h2>${icon('estimator')}</div><div class="formgrid">${[['qty',t('কেনার পরিমাণ','Purchase quantity'),500],['buy',t('প্রতি একক ক্রয়মূল্য','Buying price per unit'),60],['sell',t('প্রতি একক বিক্রয়মূল্য','Selling price per unit'),70],['freight',t('পরিবহন খরচ','Transport cost'),1000],['sold',t('বিক্রি হবে কত?','Expected quantity sold'),500],['other',t('অন্যান্য খরচ','Other expenses'),0]].map(([id,l,v])=>`<div class="field"><label for="est-${id}">${l}</label><input id="est-${id}" type="number" min="0" step="0.01" value="${v}" oninput="calculate()"></div>`).join('')}</div><p class="muted">${t('পরিবহন পণ্যের খরচের সঙ্গে ধরা হয়েছে।','Transport is included in the cost of your goods.')}</p></section><section class="estimate-result" id="estimate-result"></section></div>`}
function calculate(){if(!document.querySelector('#est-qty'))return;const v=id=>Number(document.querySelector('#est-'+id).value);let q=v('qty'),b=v('buy'),s=v('sell'),f=v('freight'),sold=v('sold'),o=v('other');const el=document.querySelector('#estimate-result');if([q,b,s,f,sold,o].some(x=>!Number.isFinite(x)||x<0)||sold>q){el.innerHTML=`<h2>${t('পরিমাণ ঠিক করুন','Check the quantities')}</h2><p>${t('সব মান শূন্য বা বেশি হবে। বিক্রির পরিমাণ কেনার চেয়ে বেশি হতে পারে না।','Values must be nonnegative. Quantity sold cannot exceed quantity purchased.')}</p>`;return}let cost=q?((q*b+f)/q):0,revenue=sold*s,net=revenue-sold*cost-o;el.innerHTML=`<span>${t('সম্ভাব্য নিট লাভ','Estimated net profit')}</span><strong class="big">${money(net)}</strong><div class="row between"><span>${t('মোট বিনিয়োগ','Cash required')}</span><b>${money(q*b+f+o)}</b></div><div class="row between"><span>${t('সম্ভাব্য বিক্রি','Expected sales')}</span><b>${money(revenue)}</b></div><div class="row between"><span>${t('বিক্রি হওয়া পণ্যের খরচ','Cost of goods sold')}</span><b>${money(sold*cost)}</b></div><div class="row between"><span>${t('অবশিষ্ট স্টকের মূল্য','Remaining stock value')}</span><b>${money((q-sold)*cost)}</b></div><p class="muted">${t('এই হিসাব একটি অনুমান, নিশ্চিত লাভ নয়।','An estimate to help you plan, not a guaranteed return.')}</p>`}
function legacyInvoices(){return head(t('ইনভয়েস','Your invoices'),t('প্রতিটি বিক্রির একটি পরিষ্কার রসিদ।','A clear receipt for every sale.'))+`<section class="panel">${salesTable(db.sales)}</section>`}
function legacyInvoice(id){const s=db.sales.find(x=>x.id===id);show(`<div style="text-align:center"><span class="tag">${t('ডেমো ইনভয়েস','DEMO INVOICE')}</span><h2 style="margin-top:16px">${t('রহিম জেনারেল স্টোর','Rahim General Store')}</h2><p class="muted">${t('মিরপুর, ঢাকা','Mirpur, Dhaka')} · 01712-345678</p><b>INV-${s.id}</b></div><div class="receipt"><p>${party(s.customer)}</p>${s.items.map(i=>`<div class="row between"><span>${esc(lang==='bn'?i.bn:i.name)}<small class="muted" style="display:block">${num(i.qty)} ${i.unit} × ${money(i.price)}</small></span><b>${money(i.qty*i.price)}</b></div>`).join('')}<div class="row between"><b>${t('মোট','Total')}</b><b>${money(s.total)}</b></div><div class="row between"><span>${t('বর্তমানে পরিশোধিত','Currently paid')}</span><span>${money(s.paid)}</span></div><div class="row between"><span>${t('বর্তমান বাকি','Current due')}</span><b>${money(s.total-s.paid)}</b></div></div><p class="muted" style="text-align:center">${t('ধন্যবাদ। আবার আসবেন!','Thank you. See you again!')}</p><button class="btn primary full no-print" onclick="window.print()">${icon('invoice')}${t('প্রিন্ট / PDF হিসেবে সেভ','Print / Save as PDF')}</button>`)}
function reports(){return head(t('ব্যবসার রিপোর্ট','Your business, in numbers'),t('আজকের নমুনা লেনদেন থেকে হিসাব।','Calculated from today’s sample transactions.'))+`<section class="metrics">${metric(t('বিক্রি','Sales'),money(totalSales()),t('মোট বিক্রয়মূল্য','Recorded sales'),'sales')}${metric(t('পণ্যের খরচ','Cost of goods sold'),money(db.sales.reduce((s,x)=>s+x.cost,0)),t('বিক্রির সময়ের খরচ','Cost at the time of sale'),'stock')}${metric(t('পরিচালন খরচ','Operating expenses'),money(expenseTotal()),t('একবারই বাদ দেওয়া হয়েছে','Deducted once'),'expenses')}${metric(t('নিট লাভ','Net profit'),money(profit()),t('বিক্রি − পণ্যের খরচ − খরচ','Sales − product costs − expenses'),'profit')}</section><section class="panel"><div class="panelhead"><h2>${t('বিক্রির বিবরণ','Sales breakdown')}</h2></div>${salesTable(db.sales)}</section>`}
function settings(){return head(t('আপনার দোকান, আপনার মতো','Your shop, your way'),t('ডেমোর সেটিংস এবং সীমাবদ্ধতা।','Demo preferences and what’s included.'))+`<section class="panel"><div class="stockrow"><div class="detail"><b>${t('ভাষা','Language')}</b><small>${t('পুরো ডেমোর ভাষা বদলান','Change the demo interface language')}</small></div><button class="btn" onclick="lang=lang==='bn'?'en':'bn';render()">${lang==='bn'?'English':'বাংলা'}</button></div><div class="stockrow"><div class="detail"><b>${t('ব্যবহারকারী','Your role')}</b><small>${t('মালিকের নমুনা ভিউ। এখানে বাস্তব লগইন নেই।','Sample Owner view. No real authentication in this frontend.')}</small></div><span class="tag">Owner</span></div><p class="notice" style="margin-top:20px">${t('এই ডেমো বাস্তব ব্যবসার তথ্যের জন্য নয়। সার্ভার, নিরাপত্তা, মাল্টি-ইউজার সিঙ্ক, রিটার্ন এবং আসল পেমেন্ট এখানে যুক্ত নেই।','This demo is not for real business records. Backend security, multi-user sync, returns and real payment processing are not connected.')}</p><button class="btn danger" onclick="resetDemo()">${t('নমুনা তথ্য রিসেট করুন','Reset sample data')}</button></section>`}
function more(){show(`<h2>${t('আরও','More')}</h2><nav class="nav">${['shops','purchase','customers','expenses','reports','invoice','settings'].map(k=>`<button onclick="closeDialog();navigate('${k}')">${icon(k)}${label(k)}</button>`).join('')}</nav>`)}
function resetDemo(){show(`<h2>${t('ডেমো রিসেট করবেন?','Reset the demo?')}</h2><p>${t('এই ব্রাউজারে আপনার যোগ করা নমুনা লেনদেন মুছে শুরুর তথ্য ফিরিয়ে আনা হবে।','Your sample changes in this browser will be replaced with the starting dataset.')}</p><button class="btn primary full" onclick="db=seed();cart=[];save();closeDialog();render();toast(t('ডেমো রিসেট হয়েছে','Demo reset'))">${t('হ্যাঁ, রিসেট করুন','Yes, reset demo')}</button>`)}
const originalRender=render;render=function(){originalRender();if(page==='estimator')calculate()};
